"""
Pytest test suite for the `/user` endpoint of a RESTful API.

Setup and Execution:
- Ensure `conftest.py` and `validator.py` are in the same directory.
- Place `api.json` (OpenAPI spec) in the directory.
- Place `user.json` (test data) in the directory.
- Run the tests using `pytest` command.

This suite tests:
- Successful user creation with valid data.
- Handling of invalid authentication.
- Various response status codes.
"""

import pytest
import json
from pathlib import Path
from validator import SwaggerSchemaValidator

# Constants and setup
HERE = Path(__file__).resolve().parent
API_SPEC_PATH = HERE / "api.json"
TEST_DATA_PATH = HERE / "user.json"
validator = SwaggerSchemaValidator(str(API_SPEC_PATH))

# Load test data
def load_json_file(file_path):
    with open(file_path, 'r') as file:
        return json.load(file)

ENDPOINT_TEST_DATA = load_json_file(TEST_DATA_PATH)

# Parametrize data
PARAM_CASES = ENDPOINT_TEST_DATA
PARAM_IDS = [f"Scenario: {case['scenario']}, ID: {case['id']}" for case in ENDPOINT_TEST_DATA]

@pytest.mark.parametrize("scenario_case", PARAM_CASES, ids=PARAM_IDS)
def test_create_user_success(api_client, host, petstore_auth, scenario_case):
    """
    Test the /user endpoint for user creation with valid data and authentication.
    """
    endpoint = "/user"
    headers = {
        "Authorization": f"Bearer {petstore_auth}",
        "Content-Type": "application/json"
    }
    
    # Prepare request body
    request_body = {key: value for key, value in scenario_case.items() if key in ["id", "username", "firstName", "lastName", "email", "password", "phone", "userStatus"]}
    
    # Validate request body
    validation_result = validator.validate_json(request_body, "User")
    assert validation_result["valid"], f"Request validation failed: {validation_result.get('message')}"

    # Make API call
    response = api_client.post(endpoint, headers=headers, data=json.dumps(request_body))

    # Validate response status code
    assert response.status_code == scenario_case['statusCode'], f"Expected {scenario_case['statusCode']}, got {response.status_code}"

    # Validate response schema
    schema_validation = validator.validate_schema_by_response(endpoint, "post", str(response.status_code), response)
    assert schema_validation["valid"], f"Response validation failed: {schema_validation.get('message')}"

@pytest.mark.parametrize("scenario_case", PARAM_CASES, ids=PARAM_IDS)
def test_create_user_invalid_auth(api_client, host, scenario_case):
    """
    Test the /user endpoint with invalid authentication.
    """
    endpoint = "/user"
    invalid_token = "invalid_token"
    headers = {
        "Authorization": f"Bearer {invalid_token}",
        "Content-Type": "application/json"
    }

    # Prepare request body
    request_body = {key: value for key, value in scenario_case.items() if key in ["id", "username", "firstName", "lastName", "email", "password", "phone", "userStatus"]}

    # Validate request body
    validation_result = validator.validate_json(request_body, "User")
    assert validation_result["valid"], f"Request validation failed: {validation_result.get('message')}"

    # Make API call
    response = api_client.post(endpoint, headers=headers, data=json.dumps(request_body))

    # Check for unauthorized status code (401)
    assert response.status_code == 401, f"Expected 401 Unauthorized, got {response.status_code}"
